OUT=ROOT/'data/parts/research.json'
N='Not specified'
benchmarks=[];tasks=[]
def title(s):return re.sub(r'[_-]+',' ',s).strip().title()
def slug(s):return re.sub(r'[^a-z0-9]+','-',str(s).lower()).strip('-')
def clean(s):return re.sub(r'\s+',' ',re.sub(r'[`#*]','',str(s))).strip()
def read(k,p):return (CACHE/k/p).read_text(errors='replace')
def url(k,p=''):return 'https://github.com/'+REPOS[k]+('/blob/'+tree(k).get('commit',tree(k)['branch'])+'/'+p if p else '')
def source(label,u):return {'label':label,'url':u}
def meta(k,name,org,cat,desc,overview,site,count,gpu=N,budget=N,paper='',priority=False,tags=None,note=''):
 b=dict(id=k,name=name,organization=org,category=cat,description=desc,overview=overview,website=site,repository=url(k) if k in REPOS else 'https://github.com/Emulated-Labs/autoresearch-bench',paper=paper,priority=priority,tags=tags or [],gpu=gpu,timeBudget=budget,taskCountReported=count,coverageNote=note,sources=[source('Official overview',site)],reviewedAt='2026-10-04')
 if b['repository']:b['sources'].append(source('Official repository',b['repository']))
 if paper:b['sources'].append(source('Paper',paper))
 benchmarks.append(b);return b
def add(k,ident,name,summary,instructions,u,**kw):
 b=next(b for b in benchmarks if b['id']==k)
 d=dict(id=k+'--'+slug(ident),benchmarkId=k,name=name,category=b['category'],summary=summary,objective=summary,instructions=instructions,instructionType='source',gpu='Suite-level: '+b['gpu'] if b['gpu']!=N else N,timeBudget='Suite-level: '+b['timeBudget'] if b['timeBudget']!=N else N,constraints=[],submission=N,evaluation=N,access='public',sourceUrl=u,sources=[source('Task specification',u)],tags=[])
 d.update(kw);tasks.append(d);return d
def first(s,limit=250):
 paras=[clean(x) for x in re.split(r'\n\s*\n',s) if clean(x) and not x.lstrip().startswith(('#','```','<!--'))]
 return (paras[0][:limit] if paras else clean(s)[:limit])
def section(s,patterns,maxlen=1200):
 parts=re.split(r'(?m)^(#{1,5} .+)$',s)
 hits=[]
 for i in range(1,len(parts),2):
  if re.search(patterns,parts[i],re.I):hits.append(clean(parts[i+1] if i+1<len(parts) else ''))
 return '\n'.join(hits)[:maxlen] or N
def gpu_config(c):
 e=c.get('environment',{});n=e.get('gpus');types=e.get('gpu_types',[])
 return 'CPU only (0 GPUs in task config)' if n==0 else (str(n)+' GPU'+('s' if n!=1 else '')+(' · '+', '.join(types) if types else ' · model not specified') if n else N)
def time_config(c):
 secs=c.get('agent',{}).get('timeout_sec');return f'{secs/3600:g} hours (agent task config)' if secs else N

def licensed(k,p,text,license):return text+'\n\n---\nSource: ['+REPOS[k]+']('+url(k,p)+'). '+license+'. Original task text; repository license and attribution apply.'

